pub fn read_counter(journal: &FjallJournal) -> Result<Option<u64>, BoxError> {
    let Some(raw) = journal.artifact_acceptance.get(b"last_issued")? else {
        return Ok(None);
    };
    let arr: [u8; 8] = raw.as_ref().try_into()?;
    Ok(Some(u64::from_be_bytes(arr)))
}

